// Solution script to add the product "REAL Jesus Clothes from Jerusalem" 
// listed as 'in stock' and priced at $45.99

document.addEventListener('DOMContentLoaded', async function() {
    try {
        // Wait for the form elements to be visible
        await new Promise(resolve => {
            const checkExist = setInterval(() => {
                if (document.querySelector('input[name="product[name]"]') && 
                    document.querySelector('input[name="product[price]"]') &&
                    document.querySelector('input[name="product[stock]"]')) {
                    clearInterval(checkExist);
                    resolve();
                }
            }, 100);
        });

        // Get values from global variables
        const authenticity = window.productAuthenticity;
        const item = window.productItem;
        const origin = window.productOrigin;
        const stockLevel = window.stockLevel;
        const price = window.listPrice;

        // Assemble the product name
        const productName = authenticity + ' ' + item + ' ' + origin;

        // Fill the form fields
        document.querySelector('input[name="product[name]"]').value = productName;
        document.querySelector('input[name="product[price]"]').value = price;
        document.querySelector('input[name="product[stock]"]').value = stockLevel;

        console.log('Product details added to form:');
        console.log('- Name:', productName);
        console.log('- Price: $', price);
        console.log('- Stock:', stockLevel);

        // Click the save button
        document.getElementById('save-button').click();

        console.log('Product form submitted successfully');
    } catch (error) {
        console.error('Error populating form:', error);
    }
});

